sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.f = {};
  c.error = '';
  c.sent = false;

  c.submit = function() {
    c.error = '';
    c.sent = false;
    c.server.get({ action: 'submit', f: c.f }).then(function(r) {
      if (r.data.error) {
        c.error = r.data.error;
      } else {
        c.sent = true;
        c.f = {};
      }
    });
  };
};

sp_widget.script:
(function() {
  var P = gs.getCurrentScopeName();

  data.rooms = [];
  var r = new GlideRecord(P + '_meeting_room'); r.orderBy('name'); r.query();
  while (r.next()) data.rooms.push({sys_id: r.getUniqueValue(), name: r.getValue('name')});

  // Issue Type choices come from the field itself, so they always match Akeah's table
  data.types = [];
  var ch = new GlideRecord('sys_choice');
  ch.addQuery('name', P + '_room_complaint');
  ch.addQuery('element', 'issue_type');
  ch.addQuery('inactive', false);
  ch.orderBy('sequence');
  ch.query();
  while (ch.next()) data.types.push({value: ch.getValue('value'), label: ch.getValue('label')});

  if (input && input.action == 'submit') {
    var f = input.f || {};
    if (!f.room || !f.type || !f.desc) {
      data.error = 'Please fill in the Meeting Room, Issue Type and Description.';
      return;
    }
    var g = new GlideRecord(P + '_room_complaint');
    g.initialize();   // also applies the default State (Open)
    g.setValue('meeting_room', f.room);
    g.setValue('issue_type', f.type);
    g.setValue('description', f.desc.substring(0, 1000));
    g.setValue('reported_by', gs.getUserID());
    g.insert();
  }
})();
